SAFE,LATE=_DATA["safe"],_DATA["late"]
_ROUTE={}
ACTION_SHA256='56a36248e0230b8a7bb6746604abe2bc9990bb4f0f3eb0f0ab6517b01f908fac'
def agent(observation,configuration=None):
 p=int(observation.get("player",0));step=min(int(observation.get("step",0)),len(SAFE[p])-1)
 if step==0:_ROUTE[p]=False
 elif step==1:
  try:
   opp=observation["farms"][1-p];_ROUTE[p]=not (float(opp["money"])==3000 and len(opp["hands"])==0)
  except Exception:_ROUTE[p]=False
 source=LATE if _ROUTE.get(p,False) else SAFE
 action=copy.deepcopy(source[p][step]);action["hands"]=action.get("hands",[])[:len(observation["farms"][p]["hands"])]
 return action
act=agent
